// RRCA interface localisation and contextual help. Does not alter radio text or engine settings.
(() => {
  'use strict';
  const words = {"Kein Spiel verbunden": ["No game connected", "Ningún simulador conectado"], "Vorschau": ["Preview", "Vista previa"], "Funktionsseiten": ["App pages", "Páginas de la aplicación"], "Team & Stimmen": ["Team & voices", "Equipo y voces"], "KI & Funk": ["AI & radio", "IA y radio"], "DEINE CREW.": ["YOUR CREW.", "TU EQUIPO."], "DEIN RENNEN.": ["YOUR RACE.", "TU CARRERA."], "Wartet auf das Spiel": ["Waiting for the game", "Esperando al simulador"], "Alles im Blick. Dein Team am Funk.": ["The whole race. Your team on the radio.", "Toda la carrera. Tu equipo por radio."], "Spiel starten und ins Auto setzen, die Crew legt von selbst los.": ["Start the game and enter the car with automatic detection enabled.", "Inicia el simulador y entra en el coche con la detección automática activada."], "Altes Fenster": ["Classic AI window", "Ventana clásica de IA"], "Crew-Chief-Fenster": ["Crew Chief window", "Ventana de Crew Chief"], "Spiel": ["Game", "Simulador"], "Erkennt das laufende Spiel und startet die Crew von selbst": ["Detects the running game and starts the crew automatically", "Detecta el simulador y activa el equipo automáticamente"], "Spiel automatisch erkennen": ["Detect game automatically", "Detectar simulador automáticamente"], "Start": ["Start", "Iniciar"], "Stopp": ["Stop", "Detener"], "Lautstärken": ["Volume controls", "Volumen"], "Funklautstärke · Messages": ["Radio volume · Messages", "Volumen de radio · Mensajes"], "Funklautstärke": ["Radio volume", "Volumen de radio"], "Hintergrund · Background": ["Background audio", "Sonido de fondo"], "Hintergrundlautstärke": ["Background volume", "Volumen de fondo"], "Direkt regelbar, ohne Neustart. Funkpegel gilt für neue Ansagen und Stimmenproben; Hintergrund 0 % schaltet das Hintergrundgeräusch aus.": ["Changes apply immediately. Radio volume affects new calls and voice tests; 0% background mutes the ambience.", "Los cambios se aplican al instante. El volumen de radio afecta a nuevos mensajes y pruebas; fondo al 0 % silencia el ambiente."], "Position": ["Position", "Posición"], "Runde": ["Lap", "Vuelta"], "Restzeit": ["Time remaining", "Tiempo restante"], "Abstand": ["Gap", "Diferencia"], "Deine Crew": ["Your crew", "Tu equipo"], "Stimmen & Geräte ↗": ["Voices & devices ↗", "Voces y dispositivos ↗"], "Strategie": ["Strategy", "Estrategia"], "Renningenieur": ["Race engineer", "Ingeniero de carrera"], "Spotterin": ["Spotter", "Spotter"], "Ben aktivieren": ["Enable Ben", "Activar a Ben"], "Mik aktivieren": ["Enable Mik", "Activar a Mik"], "Sara aktivieren": ["Enable Sara", "Activar a Sara"], "Funk": ["Radio", "Radio"], "Noch kein Funkspruch.": ["No radio call yet.", "Aún no hay mensajes."], "Saras Seitenwarnungen kommen direkt vom Spotter und stehen nicht im Verlauf.": ["Sara's side warnings come directly from the spotter and are not listed here.", "Los avisos laterales de Sara proceden directamente del spotter y no aparecen aquí."], "Letzte Funksprüche": ["Recent radio calls", "Últimos mensajes"], "Diese Session": ["This session", "Esta sesión"], "Noch nichts gefunkt.": ["No calls yet.", "Aún no hay mensajes."], "Ben, wie steht es um den Sprit?": ["Ben, how is our fuel?", "Ben, ¿cómo vamos de combustible?"], "Frage an die Crew": ["Question for the crew", "Pregunta al equipo"], "Senden": ["Send", "Enviar"], "Funk einstellen": ["Radio settings", "Ajustes de radio"], "Die Frage läuft wie ein Funkspruch über Telemetrie und Stimme, nur ohne Mikrofon. Im Auto weiter die Funktaste nutzen.": ["Uses telemetry and your selected voice, without the microphone. Use push-to-talk while driving.", "Utiliza telemetría y tu voz seleccionada, sin micrófono. Al conducir, utiliza el botón de radio."], "Team & Audio": ["Team & audio", "Equipo y audio"], "Drei Persönlichkeiten. Deine Stimmen.": ["Three personalities. Your voices.", "Tres personalidades. Tus voces."], "Nur Sara": ["Sara only", "Solo Sara"], "ElevenLabs-Stimme": ["ElevenLabs voice", "Voz de ElevenLabs"], "Bens Stimme": ["Ben's voice", "Voz de Ben"], "Miks Stimme": ["Mik's voice", "Voz de Mik"], "Saras Stimme": ["Sara's voice", "Voz de Sara"], "Probe": ["Test", "Probar"], "Rennfunk im Stand anhören": ["Preview radio while stopped", "Probar mensajes con el coche parado"], "Rennsituation": ["Race situation", "Situación de carrera"], "Erstes Überholen": ["First overtake", "Primer adelantamiento"], "Weiteres Überholen": ["Another overtake", "Otro adelantamiento"], "Abstand nach vorn": ["Gap ahead", "Diferencia por delante"], "Gegner fährt an die Box": ["Opponent enters pits", "Rival entra en boxes"], "Platzgewinn an der Box": ["Position gained through a stop", "Posición ganada por una parada"], "Sprit und Reichweite": ["Fuel and range", "Combustible y autonomía"], "Persönliche Bestzeit": ["Personal best lap", "Mejor vuelta personal"], "Gemessener Tempovorteil": ["Measured pace advantage", "Ventaja de ritmo medida"], "Podium im Ziel": ["Podium finish", "Podio al terminar"], "Stimme": ["Voice", "Voz"], "Variante": ["Variant", "Variante"], "Funkspruch anhören": ["Preview radio call", "Escuchar mensaje"], "Beispieldaten. Die Probe nutzt deinen Sprachanbieter. Vorlagen liegen in Rennfunk.de.json neben der EXE. Änderungen gelten ab dem nächsten Start.": ["Example data. Tests use your speech provider. Templates are in Rennfunk.de.json beside the EXE; changes apply on restart.", "Datos de ejemplo. Las pruebas utilizan tu proveedor de voz. Las plantillas están en Rennfunk.de.json junto al EXE; los cambios requieren reiniciar."], "Miks deutsche Zahlenaussprache vergleichen": ["Compare Mik's German number pronunciation", "Comparar la pronunciación alemana de números de Mik"], "Ziffern vorlesen": ["Read digits", "Leer cifras"], "Ausgeschriebene Zahlen vorlesen": ["Read numbers written as words", "Leer números escritos con palabras"], "Vergleicht dieselben Werte mit Miks gewählter Stimme und dem aktuellen Stimmmodell. Für die Probe Crew Chief stoppen. Bei einer anderen Stimme oben „Mik“ ändern und erneut vergleichen. Eine Probe nutzt deinen Sprachanbieter.": ["Compares the same values using Mik's selected voice and speech model. Stop Crew Chief first. Tests use your speech provider.", "Compara los mismos valores con la voz y el modelo de Mik. Detén Crew Chief antes. Las pruebas utilizan tu proveedor de voz."], "Stimmenliste laden": ["Load voice list", "Cargar lista de voces"], "Funkclips vorbereiten": ["Prepare radio clips", "Preparar clips de radio"], "Sara als Spotter erzeugen": ["Generate Sara spotter pack", "Generar paquete de Sara"], "Keine automatische Ersatzstimme": ["No automatic substitute voice", "Sin voz de sustitución automática"], "Geräte & Funktaste": ["Devices & push-to-talk", "Dispositivos y botón de radio"], "Mikrofon": ["Microphone", "Micrófono"], "Funktaste": ["Push-to-talk button", "Botón de radio"], "Funkfilter auf den Stimmen": ["Radio filter on voices", "Filtro de radio en las voces"], "Funktaste zuweisen: im Crew-Chief-Hauptfenster unter „Controller“ die Aktion „KI-Team anfunken“.": ["Assign the controller action “KI-Team anfunken” in the Crew Chief window.", "Asigna la acción del mando «KI-Team anfunken» en la ventana de Crew Chief."], "Dienste & Schlüssel": ["Services & keys", "Servicios y claves"], "Die Schlüssel werden verschlüsselt nur für deinen Windows-Benutzer gespeichert.": ["Keys are stored encrypted for your Windows user only.", "Las claves se guardan cifradas para tu usuario de Windows."], "OpenRouter (Ben, Mik, Spracherkennung) ·": ["OpenRouter (Ben, Mik, speech recognition) ·", "OpenRouter (Ben, Mik, reconocimiento de voz) ·"], "Speichern": ["Save", "Guardar"], "Löschen": ["Delete", "Eliminar"], "ElevenLabs (Stimmen) ·": ["ElevenLabs (voices) ·", "ElevenLabs (voces) ·"], "Verbindung testen": ["Test connection", "Probar conexión"], "Intelligenz & Kommunikation": ["Intelligence & communication", "Inteligencia y comunicación"], "Dein Funk. Dein Rhythmus.": ["Your radio. Your rhythm.", "Tu radio. Tu ritmo."], "Ereignisse zuerst – regelmäßige Berichte ergänzen das Team.": ["Events come first; scheduled reports support the crew.", "Los eventos tienen prioridad; los informes periódicos complementan al equipo."], "Funkmodus": ["Radio mode", "Modo de radio"], "Normal": ["Normal", "Normal"], "Minimal": ["Minimal", "Mínimo"], "Aktiv": ["Active", "Activo"], "Dein Fahrerprofil": ["Your driver profile", "Tu perfil de piloto"], "Vollständiger Name": ["Full name", "Nombre completo"], "z. B. Alex Beispiel": ["e.g. Alex Example", "p. ej. Alex Ejemplo"], "Spitzname / Funkname": ["Nickname / radio name", "Apodo / nombre por radio"], "z. B. Alex": ["e.g. Alex", "p. ej. Alex"], "Die Crew verwendet deinen Funknamen für Begrüßungen, Gespräche und persönliche Ansagen. Ohne Spitznamen verwendet sie deinen vollständigen Namen.": ["The crew uses your radio name in greetings and conversations. Without a nickname, it uses your full name.", "El equipo utiliza tu apodo en saludos y conversaciones. Sin apodo, utiliza tu nombre completo."], "Modelle & Antworten": ["Models & responses", "Modelos y respuestas"], "Schnelle Antworten": ["Fast responses", "Respuestas rápidas"], "Vertiefte Analysen": ["Detailed analysis", "Análisis detallado"], "Spracherkennung": ["Speech recognition", "Reconocimiento de voz"], "ElevenLabs-Stimmmodell": ["ElevenLabs speech model", "Modelo de voz de ElevenLabs"], "Denkaufwand beim API-Anbieter": ["Reasoning effort at API provider", "Esfuerzo de razonamiento del proveedor API"], "None · kein zusätzlicher Denkaufwand": ["None · no extra reasoning", "None · sin razonamiento adicional"], "Niedrig": ["Low", "Bajo"], "Mittel": ["Medium", "Medio"], "Hoch": ["High", "Alto"], "Maximale KI-Aufrufe je Session": ["Maximum AI calls per session", "Máximo de consultas de IA por sesión"], "Höherer Denkaufwand gilt für vertiefte Analysen im Stand. Zeitkritischer Fahrfunk nutzt höchstens „Niedrig“. „None“ bleibt ohne zusätzlichen Denkaufwand. Die lokale Ereigniserkennung und Sara arbeiten unabhängig davon.": ["Higher reasoning applies to detailed analysis while stopped. Time-sensitive driving radio uses at most Low. None adds no reasoning. Local event detection and Sara remain independent.", "El razonamiento alto se aplica a análisis con el coche parado. La radio durante la conducción utiliza como máximo Bajo. None no añade razonamiento. La detección local y Sara son independientes."], "Regelmäßige Funkberichte": ["Scheduled radio reports", "Informes periódicos por radio"], "Das Team erkennt relevante Ereignisse eigenständig. Diese Intervalle ergänzen die Ereignismeldungen; Saras direkte Warnungen bleiben unabhängig.": ["The crew detects relevant events independently. These intervals supplement event calls; Sara's immediate warnings stay independent.", "El equipo detecta eventos relevantes por sí mismo. Los intervalos complementan los avisos; las alertas inmediatas de Sara son independientes."], "Ruhiger Teamfunk, anpassbare Abstände": ["Calm team radio, adjustable intervals", "Radio tranquila con intervalos ajustables"], "Empfohlene Abstände einsetzen": ["Use recommended intervals", "Usar intervalos recomendados"], "Bericht": ["Report", "Informe"], "An": ["On", "Activado"], "Alle / s": ["Every / s", "Cada / s"], "Beispiel: 120 −7/+8 bedeutet eine Planung zwischen 113 und 128 Sekunden. Dringender Funk und fehlende Messwerte können den Bericht zurückstellen. Zwischen Routineberichten liegen mindestens 20 Sekunden. Im Modus Normal werden identische Technik- und Wetterberichte gebündelt. Aktiv meldet auch unveränderte Werte im gewählten Intervall; bestätigte Qualifying-Flugrunden bleiben von Routineberichten frei.": ["Example: 120 −7/+8 schedules a report after 113–128 seconds. Urgent radio or missing data may defer it. Routine calls are at least 20 seconds apart. Normal merges unchanged technical/weather reports. Active also reports unchanged values; confirmed qualifying push laps remain quiet.", "Ejemplo: 120 −7/+8 programa un informe entre 113 y 128 segundos. La radio urgente o datos ausentes pueden aplazarlo. Hay al menos 20 segundos entre informes. Normal agrupa informes técnicos o de tiempo sin cambios. Activo también comunica valores sin cambios; las vueltas lanzadas confirmadas de clasificación quedan libres de informes."], "Dauerhaftes Fahrergedächtnis": ["Persistent driver memory", "Memoria persistente del piloto"], "Gespräche, Wünsche und Korrekturen merken": ["Remember conversations, preferences and corrections", "Recordar conversaciones, preferencias y correcciones"], "Bleibt bei Updates erhalten. Nur Texte, keine Mikrofonaufnahmen. Relevante Erinnerungen werden bei KI-Gesprächen an deinen Anbieter übermittelt.": ["Persists across updates. Text only, no microphone recordings. Relevant memories are sent to your provider during AI conversations.", "Se conserva tras las actualizaciones. Solo texto, sin grabaciones de micrófono. Los recuerdos relevantes se envían a tu proveedor durante conversaciones con IA."], "Gedächtnisordner öffnen": ["Open memory folder", "Abrir carpeta de memoria"], "Fahrer, Telemetrie & Diagnose": ["Driver, telemetry & diagnostics", "Piloto, telemetría y diagnóstico"], "Lokalen Diagnoserecorder einschalten": ["Enable local diagnostic recorder", "Activar grabador local de diagnóstico"], "Begrenzte lokale Aufzeichnung: 128 MiB je Session · 512 MiB insgesamt. Keine Roh-Mikrofonaufnahmen oder Zugangsschlüssel.": ["Bounded local recording: 128 MiB per capture, 512 MiB total. No raw microphone recordings or access keys.", "Registro local limitado: 128 MiB por grabación, 512 MiB en total. Sin audio de micrófono ni claves de acceso."], "Diagnoseordner": ["Diagnostics folder", "Carpeta de diagnóstico"], "KI-Zeitlimit / Sekunden": ["AI timeout / seconds", "Tiempo límite de IA / segundos"], "Modelle und Berichte bei gestopptem Crew Chief übernehmen, sie gelten ab dem nächsten Start.": ["Apply models and reports while Crew Chief is stopped; they take effect on the next crew start.", "Aplica modelos e informes con Crew Chief detenido; se utilizarán al iniciar el equipo."], "Übernehmen": ["Apply", "Aplicar"], "RRCA · Rob’s Race Crew Advanced · Vorschau": ["RRCA · Rob’s Race Crew Advanced · Preview", "RRCA · Rob’s Race Crew Advanced · Vista previa"], "Basiert auf Crew Chief V4 (Britton IT Ltd, MIT-Lizenz) ·": ["Based on Crew Chief V4 (Britton IT Ltd, MIT licence) ·", "Basado en Crew Chief V4 (Britton IT Ltd, licencia MIT) ·"], "Hinweise, Lizenz und Dank": ["Notices, licence & credits", "Avisos, licencia y agradecimientos"], "Oberflächensprache": ["Interface language", "Idioma de la interfaz"], "Die Sprachwahl übersetzt die Oberfläche und Hilfen. Die Sprache des Funks stellst du unter KI & Funk ein.": ["This changes the interface and help. Set the radio language under AI & radio.", "Esta selección cambia la interfaz y la ayuda. El idioma de la radio se ajusta en IA y radio."], "Funksprache": ["Radio language", "Idioma de la radio"], "Automatisch (Windows)": ["Automatic (Windows)", "Automático (Windows)"], "Hilfe": ["Help", "Ayuda"], "Schließen": ["Close", "Cerrar"], "Ausgeschaltet": ["Disabled", "Desactivado"], "● Funkt gerade": ["● On the radio", "● Hablando por radio"], "Noch nicht bereit, siehe Hinweis oben": ["Not ready yet; see notice above", "Aún no está lista; consulta el aviso superior"], "Beobachtet die Strategie": ["Watching strategy", "Observando la estrategia"], "Beobachtet das Fahrzeug": ["Monitoring the car", "Vigilando el coche"], "Hat die Seiten im Blick": ["Watching alongside", "Vigilando los laterales"], "Gespeicherte Stimme": ["Saved voice", "Voz guardada"], "Stimme auswählen": ["Choose a voice", "Seleccionar voz"], "Windows-Standardgerät": ["Windows default device", "Dispositivo predeterminado de Windows"], "kein Schlüssel hinterlegt": ["no key stored", "sin clave guardada"], "Trage deinen Fahrernamen ein.": ["Enter your driver name.", "Introduce tu nombre de piloto."], "Live-Daten vom Spiel": ["Live data from the game", "Datos en directo del simulador"], "Quelle erreichbar · Fahrdaten fehlen": ["Source reachable · driving data missing", "Fuente accesible · sin datos de conducción"], "Automatische Spielerkennung ist aktiv. Ein eindeutig laufendes Spiel wird auch im Hintergrund erkannt. Bei mehreren laufenden Sims das gewünschte Spiel in den Vordergrund holen.": ["Automatic detection is enabled. A single running game is also detected in the background. If several sims are running, bring the desired one to the foreground.", "La detección automática está activada. Se detecta un único simulador incluso en segundo plano. Si hay varios, pon el deseado en primer plano."], "Spiel auswählen und Start drücken. Die automatische Spielerkennung ist ausgeschaltet.": ["Select a game and press Start. Automatic detection is off.", "Selecciona un simulador y pulsa Iniciar. La detección automática está desactivada."], "Die Crew läuft. Spiel starten und ins Auto setzen, damit Fahrdaten ankommen.": ["The crew is running. Start the game and enter the car to receive driving data.", "El equipo está activo. Inicia el simulador y entra en el coche para recibir datos."], "Noch keine gültigen Fahrdaten. Die Simulation kann im Menü, in der Garage oder pausiert sein.": ["No valid driving data yet. The sim may be in a menu, garage or paused.", "Aún no hay datos de conducción válidos. Puede que el simulador esté en un menú, en el garaje o en pausa."], "Erst den Schlüssel einfügen.": ["Paste the key first.", "Pega la clave primero."], "Empfohlene Abstände eingesetzt. Deine An-/Auswahl bleibt erhalten. Zum Übernehmen Einstellungen speichern.": ["Recommended intervals inserted. Enabled topics are unchanged. Save settings to apply.", "Intervalos recomendados aplicados. Se conservan los temas activados. Guarda los ajustes para aplicar."], "Diese Seite läuft nur im RRCA-Fenster von Crew Chief.": ["This page only works inside RRCA's Crew Chief window.", "Esta página solo funciona dentro de la ventana RRCA de Crew Chief."], "Crew Chief zuerst stoppen.": ["Stop Crew Chief first.", "Detén Crew Chief primero."], "Crew Chief zuerst stoppen. Modelle und Berichte gelten ab dem nächsten Start.": ["Stop Crew Chief first. Models and reports apply on the next crew start.", "Detén Crew Chief primero. Los modelos e informes se aplican al iniciar el equipo."], "Gespeichert. Die Werte gelten ab dem nächsten Start von Crew Chief.": ["Saved. Values apply on the next crew start.", "Guardado. Los valores se aplican al iniciar el equipo."], "Beide Modellnamen müssen ausgefüllt sein.": ["Enter both model names.", "Introduce ambos nombres de modelo."], "Bitte einen Fahrernamen (maximal 80 Zeichen) und optional einen Funknamen (maximal 40 Zeichen) eintragen.": ["Enter a driver name (up to 80 characters) and optionally a radio name (up to 40).", "Introduce un nombre de piloto (máximo 80 caracteres) y, opcionalmente, un apodo (máximo 40)."], "Diagnose gestoppt.": ["Diagnostics stopped.", "Diagnóstico detenido."], "Spielerkennung ist sofort aktiv. Ein laufendes Spiel wird auch im Hintergrund erkannt.": ["Automatic detection is active immediately, including in the background.", "La detección automática se activa al instante, también en segundo plano."], "Spielerkennung ist ausgeschaltet. Die laufende Crew bleibt unverändert.": ["Automatic detection is off. The running crew is unchanged.", "La detección automática está desactivada. El equipo en marcha no cambia."], "Gespeichert. Bitte Crew Chief einmal von Hand neu starten.": ["Saved. Restart Crew Chief manually while stopped.", "Guardado. Reinicia Crew Chief manualmente con el equipo detenido."], "Sara-Clips vorbereiten": ["Prepare Sara clips", "Preparar clips de Sara"], "Beheben und neu starten": ["Fix and restart", "Corregir y reiniciar"], "Schlüssel eintragen": ["Enter keys", "Introducir claves"], "Stimmeneinstellungen sind noch nicht verfügbar.": ["Voice settings are not available yet.", "Los ajustes de voz aún no están disponibles."], "KI-Team ausgeschaltet.": ["AI team disabled.", "Equipo de IA desactivado."], "Windows-Systemstimmen sind gewählt. Für die Crew eine natürliche Stimmenquelle auswählen und die Originalclips vorbereiten.": ["Windows system voices are selected. Select a natural voice provider and prepare the original clips.", "Están seleccionadas las voces de Windows. Selecciona un proveedor de voz natural y prepara los clips originales."], "Die alten Crew-Chief-Ansagen sind noch aktiv. Für ausschließlich Ben, Mik und Sara „KI-Team ersetzt Crew-Chief-Stimme“ einschalten.": ["Legacy Crew Chief calls are enabled. Enable “KI-Team ersetzt Crew-Chief-Stimme” for Ben, Mik and Sara only.", "Los mensajes clásicos de Crew Chief están activos. Activa «KI-Team ersetzt Crew-Chief-Stimme» para oír solo a Ben, Mik y Sara."], "Sara ausgeschaltet; keine Seitenwarnungen von Sara.": ["Sara disabled; no side warnings from Sara.", "Sara desactivada; no habrá avisos laterales de Sara."], "Für Saras sofortige Unterbrechungen nAudio aktivieren und die App neu starten.": ["Enable nAudio and restart the app for Sara's immediate interruptions.", "Activa nAudio y reinicia la aplicación para las interrupciones inmediatas de Sara."], "Sara ist aktiviert, aber der lokale Spotter ist ausgeschaltet. Spotter aktivieren oder Sara ausdrücklich ausschalten.": ["Sara is enabled but the local spotter is off. Enable the spotter or explicitly disable Sara.", "Sara está activada, pero el spotter local está desactivado. Activa el spotter o desactiva Sara expresamente."], "Saras Originalclips fehlen, sind beschädigt oder passen nicht zur gewählten Stimme. „Sara als Spotter erzeugen“ ausführen, danach die App vollständig neu starten.": ["Sara's clips are missing, damaged or do not match her voice. Generate Sara's spotter pack, then fully restart the app.", "Faltan los clips de Sara, están dañados o no corresponden a su voz. Genera su paquete y reinicia completamente la aplicación."], "Das Sara-Pack ist vorhanden, als lokaler Spotter ist aber eine andere Stimme gewählt. Im Crew-Chief-Hauptfenster Sara wählen und die App vollständig neu starten.": ["Sara's pack exists, but another local spotter is selected. Select Sara in Crew Chief and fully restart the app.", "Existe el paquete de Sara, pero está seleccionado otro spotter. Selecciona Sara en Crew Chief y reinicia completamente la aplicación."], "Saras gewählte Originalstimme ist vorbereitet, aber noch nicht in der Audioengine geladen. Die App vollständig schließen und neu starten.": ["Sara's selected voice is prepared but not loaded in the audio engine. Fully close and restart the app.", "La voz seleccionada de Sara está preparada, pero no cargada en el motor de audio. Cierra la aplicación y vuelve a iniciarla."], "Sara bereit – gewählte Originalstimme lokal geladen.": ["Sara ready · selected original voice loaded locally.", "Sara lista · voz original seleccionada cargada localmente."], "Das KI-Team ist in den Crew-Chief-Eigenschaften ausgeschaltet (\"KI-Team aktivieren\").": ["The AI team is disabled in Crew Chief properties (\"KI-Team aktivieren\").", "El equipo de IA está desactivado en las propiedades de Crew Chief («KI-Team aktivieren»)."], "Der OpenRouter-Schlüssel fehlt. Ben und Mik können keine KI-Fragen beantworten; vorbereitete lokale Ansagen bleiben verfügbar.": ["OpenRouter key missing. Ben and Mik cannot answer AI questions; prepared local calls remain available.", "Falta la clave de OpenRouter. Ben y Mik no pueden responder preguntas de IA; los mensajes locales preparados siguen disponibles."], "Der ElevenLabs-Schlüssel fehlt. Neue Texte können nicht gesprochen werden; vorbereitete Originalclips bleiben verfügbar.": ["ElevenLabs key missing. New texts cannot be spoken; prepared original clips remain available.", "Falta la clave de ElevenLabs. No se pueden leer textos nuevos; los clips originales preparados siguen disponibles."], "bereit – Texte lokal gespeichert": ["ready · text stored locally", "listo · textos guardados localmente"], "ausgeschaltet": ["disabled", "desactivado"], "aus": ["off", "desactivado"], "Rennstatus: Position und Abstände": ["Race status: position and gaps", "Estado de carrera: posición y diferencias"], "Wetter, Luft- und Streckentemperatur": ["Weather, air and track temperature", "Tiempo, temperatura ambiente y de pista"], "Sprit und gemessene Reichweite": ["Fuel and measured range", "Combustible y autonomía medida"], "Reifenverschleiß": ["Tyre wear", "Desgaste de neumáticos"], "Eigene Rundenzeiten und Konstanz": ["Your lap times and consistency", "Tus tiempos y regularidad"], "Vordermann: Name und Abstand": ["Car ahead: name and gap", "Coche de delante: nombre y diferencia"], "Hintermann: Name und Abstand": ["Car behind: name and gap", "Coche de detrás: nombre y diferencia"], "Stintentwicklung: Verbrauch und Reifen": ["Stint trends: fuel and tyres", "Evolución del stint: consumo y neumáticos"], "Fahrzeugzustand: Schäden und Technik": ["Car condition: damage and systems", "Estado del coche: daños y sistemas"], "Rennfortschritt und Restdistanz": ["Race progress and distance remaining", "Progreso de carrera y distancia restante"], "Aktueller Überblick; nur belegte Fortschritte und Pace.": ["Current overview; only supported progress and pace.", "Resumen actual; solo progreso y ritmo demostrados."], "Nur verfügbare Messwerte; keine Wettervorhersage.": ["Available measurements only; not a forecast.", "Solo mediciones disponibles; no es un pronóstico."], "Reichweite erst mit sauber gemessenem Verbrauch.": ["Range requires clean fuel consumption measurements.", "La autonomía requiere mediciones válidas de consumo."], "Eigene Reifen; keine erfundenen Gegnerwerte.": ["Your own tyres; no invented opponent data.", "Tus neumáticos; sin datos inventados de rivales."], "Drei zusammenhängende gültige Runden ohne Box.": ["Three consecutive valid laps without a pit visit.", "Tres vueltas válidas consecutivas sin entrar en boxes."], "Gegner der eigenen Klasse; Abstand muss bekannt sein.": ["Own-class opponent; gap must be known.", "Rival de tu clase; la diferencia debe estar disponible."], "Kein Ersatz für Saras unmittelbare Seitenwarnungen.": ["Does not replace Sara's immediate side warnings.", "No sustituye los avisos laterales inmediatos de Sara."], "Gemessene Entwicklung ohne erfundene Strategie.": ["Measured trends without invented strategy.", "Evolución medida sin estrategias inventadas."], "Motor, Bremsen, Aufhängung, Getriebe, Aero und Reifen, soweit verfügbar.": ["Engine, brakes, suspension, gearbox, aero and tyres where available.", "Motor, frenos, suspensión, cambio, aerodinámica y neumáticos, si están disponibles."], "Restzeit oder bestätigte Rundenzahl, passend zum Rennformat.": ["Time or confirmed laps remaining, according to race format.", "Tiempo o vueltas restantes confirmadas, según el formato."], "Training": ["Practice", "Entrenamientos"], "Qualifying": ["Qualifying", "Clasificación"], "Rennen": ["Race", "Carrera"], "Hotlap": ["Hotlap", "Vuelta rápida"], "Diagnose:": ["Diagnostics:", "Diagnóstico:"], "Datenschutz & Erststart": ["Privacy & first start", "Privacidad y primer inicio"], "README Deutsch": ["German README", "README alemán"], "README Englisch": ["English README", "README inglés"], "README Spanisch": ["Spanish README", "README español"], "Projekt und Lizenzen": ["Project and licences", "Proyecto y licencias"], "Fahrernamen an KI übermitteln": ["Send driver names to AI", "Enviar nombres de pilotos a la IA"], "Ausgeschaltet: Gegnernamen werden für KI-Anfragen ausgeblendet. Eigener Funkname und gesprochener Text können weiterhin an KI- und Stimmenanbieter gehen.": ["When off, opponent names are hidden from AI requests. Your radio name and spoken text can still go to AI and speech providers.", "Desactivado: se ocultan nombres de rivales en las consultas de IA. Tu apodo y texto hablado pueden seguir enviándose a proveedores de IA y voz."], "Inoffizielle Alpha für Simulationen. Fehler sind möglich. Externe Dienste können Geld kosten. Keine vollständige Rechtsfreigabe für Name, Stimmen oder fremde Inhalte.": ["Unofficial alpha for simulations. Errors are possible. External services may cost money. Name, voice and third-party content rights are not fully cleared.", "Alpha no oficial para simulación. Puede tener errores. Los servicios externos pueden tener coste. No se han autorizado por completo los derechos del nombre, voces y contenidos ajenos."], "Lautstärke muss zwischen 0 und 100 Prozent liegen.": ["Volume must be between 0 and 100 percent.", "El volumen debe estar entre el 0 y el 100 por ciento."], "Crew Chief zuerst stoppen. Audio- und Mikrofoneinstellungen gelten ab der nächsten Fahrt.": ["Stop Crew Chief first. Audio and microphone settings apply to the next drive.", "Detén Crew Chief primero. Los ajustes de audio y micrófono se aplican a la próxima sesión."], "Erst den ElevenLabs-Schlüssel speichern.": ["Save the ElevenLabs key first.", "Guarda primero la clave de ElevenLabs."], "Lade die Stimmen …": ["Loading voices …", "Cargando voces …"], "ElevenLabs-Schlüssel gespeichert, lade die Stimmen …": ["ElevenLabs key saved, loading voices …", "Clave de ElevenLabs guardada, cargando voces …"], "OpenRouter-Schlüssel gespeichert, prüfe ihn …": ["OpenRouter key saved, checking …", "Clave de OpenRouter guardada, comprobando …"], "Die vorige Aufnahme wird noch abgeschlossen.": ["The previous capture is still being finalised.", "La grabación anterior aún se está finalizando."], "Textarchiv voll oder nicht beschreibbar; Notizen bleiben erhalten": ["Text archive full or not writable; notes are preserved", "Archivo de textos lleno o no escribible; se conservan las notas"], "Nach Saras Stimmwechsel ihr Spotterpack neu erzeugen und die App im Stand neu starten. Die Crew wartet, bis Sara bereit ist. Neue deutsche Stimmen im ElevenLabs-Konto hinzufügen und die Liste neu laden.": ["After changing Sara's voice, generate her spotter pack and restart the app while stopped. The crew waits until Sara is ready. Add German voices to your ElevenLabs account, then reload the list.", "Tras cambiar la voz de Sara, genera su paquete y reinicia la aplicación con el equipo detenido. El equipo espera hasta que Sara esté lista. Añade voces alemanas a tu cuenta de ElevenLabs y recarga la lista."], "Mitglieder einzeln wählen und Stimmen zuordnen. Stimmen im Stand ändern; die Auswahl wird gespeichert.": ["Enable members individually and assign voices. Changes are saved immediately; change voices while stopped.", "Activa cada miembro y asigna sus voces. Los cambios se guardan al momento; cambia las voces con el equipo detenido."], "Auf Basis von Crew Chief V4 – mit Dank an die Entwickler": ["Based on Crew Chief V4 – with thanks to its developers", "Basado en Crew Chief V4 – gracias a sus desarrolladores"], "Inoffizielles Privatprojekt, unentgeltlich und nichtkommerziell angeboten. Der Crew-Chief-Quellcode wird gemäß MIT-Lizenz von Britton IT Ltd verwendet. KI- und Stimmendienste können separat Kosten verursachen.": ["Unofficial hobby project, offered free of charge and non-commercially. Crew Chief source is used under Britton IT Ltd’s MIT licence. AI and voice services may have separate costs.", "Proyecto personal no oficial, gratuito y no comercial. Se utiliza el código de Crew Chief bajo la licencia MIT de Britton IT Ltd. Los servicios de IA y voz pueden tener costes aparte."], "Herkunft und Lizenz": ["Origin and licence", "Origen y licencia"]}, help = {"language": {"title": "Oberflächensprache", "text": ["Deutsch, Englisch oder Spanisch für Menüs und Hilfen. Gesprochener Rennfunk und Sara-Clips bleiben derzeit deutsch. Die Auswahl wird lokal im WebView-Profil gespeichert.", "German, English or Spanish for menus and help. Spoken race radio and Sara clips currently stay German. The choice is stored locally in the WebView profile.", "Alemán, inglés o español para menús y ayuda. La radio de carrera y los clips de Sara siguen en alemán. La elección se guarda localmente en el perfil WebView."]}, "game": {"title": "Spiel", "text": ["Manuell die Simulation wählen und Start drücken. Mit automatischer Erkennung startet die Crew für eine eindeutig erkannte laufende Sim. Adapter und Spieldaten müssen eingerichtet sein; im Menü fehlen oft Fahrdaten.", "Select the simulator and press Start. Automatic detection starts the crew for a uniquely detected running sim. The adapter must be configured; menus often provide no driving data.", "Selecciona el simulador y pulsa Iniciar. La detección automática activa el equipo para un simulador identificado. El adaptador debe estar configurado; los menús suelen carecer de datos de conducción."]}, "volume": {"title": "Lautstärken", "text": ["Messages regelt neue Funksprüche und Stimmenproben. Background regelt nur das Funk-Hintergrundgeräusch, nicht das Spiel. 0 % schaltet den jeweiligen Kanal stumm. Änderungen gelten sofort.", "Messages controls new calls and voice tests. Background controls only radio ambience, not the game. 0% mutes that channel. Changes apply immediately.", "Mensajes controla avisos nuevos y pruebas de voz. Fondo controla el ambiente de radio, no el juego. El 0 % silencia ese canal. Los cambios son inmediatos."]}, "roles": {"title": "Deine Crew", "text": ["Ben: Strategie und Rennbeobachtung. Mik: Fahrzeug und Technik. Sara: unmittelbare Seitenwarnungen. Mitglieder sind einzeln schaltbar. Nur Sara schaltet Ben und Mik aus. Sara auszuschalten entfernt ihre Sicherheitswarnungen.", "Ben handles strategy and race observation, Mik car systems, Sara immediate side warnings. Members can be toggled individually. Sara only disables Ben and Mik. Disabling Sara removes her warnings.", "Ben gestiona estrategia y carrera; Mik, el coche; Sara, avisos laterales inmediatos. Cada miembro se activa por separado. Solo Sara desactiva a Ben y Mik. Desactivar Sara elimina sus avisos."]}, "voices": {"title": "ElevenLabs-Stimme", "text": ["Im Stand eigene Stimmen aus deinem ElevenLabs-Konto laden, zuordnen und testen. Eine deutsch geeignete Stimme wählen. Nach Saras Stimmwechsel ihr Spotterpack neu erzeugen und die App vollständig neu starten. Proben und Erzeugung kosten API-Guthaben.", "While stopped, load, assign and test voices from your ElevenLabs account. Choose German-capable voices. After changing Sara, regenerate her spotter pack and fully restart. Tests and generation use API credit.", "Con el equipo detenido, carga, asigna y prueba voces de tu cuenta ElevenLabs aptas para alemán. Tras cambiar Sara, regenera su paquete y reinicia. Las pruebas y generación consumen crédito API."]}, "clips": {"title": "Funkclips vorbereiten", "text": ["Bereitet bekannte Ansagen mit den gewählten Stimmen lokal vor. Das vermeidet Cloud-Wartezeit bei diesen Sätzen. Neue freie Texte brauchen weiterhin den Anbieter. Im Stand vorbereiten; keine fremden Stimmen-Caches weitergeben.", "Prepares known calls locally using your voices, avoiding cloud delay for those phrases. New free text still needs the provider. Prepare while stopped; do not redistribute voice caches.", "Prepara mensajes conocidos localmente con tus voces y evita la espera de nube para esas frases. Los textos nuevos siguen necesitando proveedor. Prepara con el equipo detenido; no redistribuyas cachés de voz."]}, "phrases": {"title": "Rennfunk im Stand anhören", "text": ["Standprobe mit Beispieldaten, kein Live-Ereignis. Situation, Sprecher und Variante 1–16 wählen. Kürzere Gruppen nutzen ihre vorhandenen Varianten. Verbraucht gegebenenfalls TTS-Guthaben.", "Stopped preview using example data, not a live event. Choose a situation, speaker and variant 1–16. Shorter groups reuse their available variants. May consume TTS credit.", "Prueba con datos de ejemplo, no un evento real. Elige situación, voz y variante 1–16. Los grupos más cortos reutilizan sus variantes. Puede consumir crédito TTS."]}, "numbers": {"title": "Miks deutsche Zahlenaussprache vergleichen", "text": ["Ziffern und ausgeschriebene Zahlen mit derselben Stimme vergleichen. Beeinflusst nicht automatisch alle Einstellungen. Bei schlechter Aussprache eine andere deutsch geeignete Stimme oder das Stimmmodell vergleichen.", "Compare digits and numbers written as words using the same voice. This does not automatically change settings. Try another German-capable voice or speech model if pronunciation is poor.", "Compara cifras y números escritos con la misma voz. No cambia automáticamente los ajustes. Si la pronunciación es mala, prueba otra voz apta para alemán o modelo de voz."]}, "mic": {"title": "Mikrofon", "text": ["Wähle das tatsächliche Aufnahmegerät. Die Funktaste im Crew-Chief-Fenster der Aktion „KI-Team anfunken“ zuordnen. Gedrückt sprechen, dann loslassen. Der Sprachabschnitt geht zur Cloud-Erkennung; keine vollständige Mikrofonaufnahme wird gespeichert.", "Select the actual recording device. Assign “KI-Team anfunken” in Crew Chief. Hold the button, speak, then release. That speech segment goes to cloud transcription; no full microphone recording is saved.", "Selecciona el dispositivo de grabación. Asigna «KI-Team anfunken» en Crew Chief. Mantén el botón, habla y suéltalo. Ese fragmento se envía a transcripción en nube; no se guarda una grabación completa."]}, "filter": {"title": "Funkfilter auf den Stimmen", "text": ["Fügt einen Funkklang hinzu, ändert nicht die Stimme. Beim Ändern können vorbereitete Clips neu benötigt werden. Bei Sara anschließend ihr Pack prüfen und gegebenenfalls neu erzeugen.", "Adds a radio effect without changing voice identity. Prepared clips may need regeneration. Check Sara’s pack afterwards and regenerate if required.", "Añade efecto de radio sin cambiar la identidad de voz. Puede ser necesario regenerar clips. Comprueba después el paquete de Sara y regénéralo si hace falta."]}, "keys": {"title": "Dienste & Schlüssel", "text": ["OpenRouter für KI und Erkennung, ElevenLabs für Stimmen. Eigene Schlüssel eintragen; Anbieter rechnen separat ab. Lokal mit Windows-DPAPI geschützt. Nur zur Authentifizierung an den jeweiligen Anbieter gesendet. Nie mit ZIP oder Log veröffentlichen.", "OpenRouter provides AI and recognition, ElevenLabs voices. Enter your own keys; provider charges are separate. Stored using Windows DPAPI and sent only to the respective provider for authentication. Never publish keys with ZIPs or logs.", "OpenRouter ofrece IA y reconocimiento; ElevenLabs, voces. Usa tus claves; los costes del proveedor son aparte. Se guardan con Windows DPAPI y se envían al proveedor para autenticar. Nunca las publiques en ZIP o registros."]}, "name": {"title": "Dein Fahrerprofil", "text": ["Vollständigen Namen und optional einen kurzen Funknamen eingeben, dann Übernehmen. Beispiel: Alex Beispiel / Alex. Die Crew nutzt bevorzugt den Funknamen. Das ist kein Benutzerkonto und ändert keine Namen im Spiel.", "Enter your full name and optionally a short radio name, then Apply. Example: Alex Example / Alex. The crew prefers the nickname. This is not an account and does not change your in-game name.", "Introduce nombre completo y un apodo opcional, y pulsa Aplicar. Ejemplo: Alex Ejemplo / Alex. El equipo prefiere el apodo. No es una cuenta ni cambia tu nombre en el juego."]}, "mode": {"title": "Funkmodus", "text": ["Normal bündelt unveränderte Routinethemen. Aktiv meldet auch unveränderte verfügbare Werte im Intervall. Minimal reduziert Teamfunk. Wichtige bestätigte Ereignisse und Saras lokale Warnungen bleiben eigenständig priorisiert.", "Normal merges unchanged routine topics. Active also reports unchanged available values on schedule. Minimal reduces chatter. Important confirmed events and Sara’s local warnings remain independently prioritised.", "Normal agrupa temas rutinarios sin cambios. Activo también comunica valores sin cambios según intervalo. Mínimo reduce mensajes. Los eventos confirmados y Sara conservan su prioridad independiente."]}, "fast": {"title": "Schnelle Antworten", "text": ["Exakte Modell-ID deines API-Anbieters eintragen. Für Funk während der Fahrt ein schnelles Modell mit guter deutscher Sprache und Werkzeugaufrufen wählen. Größere Modelle verbessern keine fehlenden Telemetriedaten.", "Enter the exact model ID from your API provider. Choose a fast model with good German and tool support for driving radio. Larger models cannot repair missing telemetry.", "Introduce la ID exacta del modelo del proveedor. Para conducir, elige un modelo rápido con buen alemán y herramientas. Un modelo mayor no repara datos de telemetría ausentes."]}, "deep": {"title": "Vertiefte Analysen", "text": ["Modell-ID für vertiefte Fragen im Stand. Darf langsamer sein, kostet oft mehr. Auf der Strecke haben kurze aktuelle Fakten Vorrang.", "Model ID for detailed questions while stopped. It can be slower and often costs more. Short, current facts take priority while driving.", "ID del modelo para preguntas detalladas con el coche parado. Puede ser más lento y costoso. Al conducir tienen prioridad hechos breves y actuales."]}, "stt": {"title": "Spracherkennung", "text": ["ID des Transkriptionsmodells eintragen. Es verarbeitet nur den über die Funktaste aufgenommenen Sprachabschnitt. Eine gute Mikrofonquelle und kurze eindeutige Fragen helfen mehr als ein größeres Chatmodell.", "Enter the transcription model ID. It processes the segment recorded with push-to-talk. A good microphone and clear short questions help more than a larger chat model.", "Introduce la ID del modelo de transcripción. Procesa el fragmento del botón de radio. Un buen micrófono y preguntas claras ayudan más que un modelo de chat mayor."]}, "tts": {"title": "ElevenLabs-Stimmmodell", "text": ["Flash v2.5 ist auf geringe Wartezeit ausgelegt; Multilingual v2 kann deutsche Aussprache verbessern, ist oft langsamer. Mit derselben Stimme vergleichen. Nach Änderung vorbereitete Clips und Sara-Pack erneuern, falls als unpassend markiert.", "Flash v2.5 targets low latency; Multilingual v2 may improve German pronunciation but is often slower. Compare using the same voice. Regenerate prepared clips and Sara’s pack if marked mismatched after a change.", "Flash v2.5 prioriza baja latencia; Multilingual v2 puede mejorar el alemán, pero suele ser más lento. Compara con la misma voz. Regenera clips y paquete Sara si dejan de corresponder tras el cambio."]}, "reasoning": {"title": "Denkaufwand beim API-Anbieter", "text": ["None: kein zusätzlicher Denkaufwand. Low/Medium/High können Standanalysen vertiefen und Kosten sowie Wartezeit erhöhen; nur soweit der Anbieter das unterstützt. Fahrfunk nutzt höchstens Low. Saras lokale Reaktion hängt nicht davon ab.", "None adds no reasoning. Low/Medium/High can deepen stopped analysis and increase costs and delay, if supported by the provider. Driving radio uses at most Low. Sara’s local response is independent.", "None no añade razonamiento. Low/Medium/High pueden profundizar análisis en parado y aumentar coste y espera si el proveedor lo admite. La radio en marcha usa como máximo Low. Sara es independiente."]}, "limit": {"title": "Maximale KI-Aufrufe je Session", "text": ["Begrenzt KI-Aufrufe pro Sitzung, nicht alle Kosten. Spracherkennung und TTS werden separat abgerechnet. Lokale Warnungen benötigen keine Chat-KI. Ein höheres Limit erzeugt nicht automatisch mehr sinnvolle Ereignisse.", "Limits AI calls per session, not all costs. Speech recognition and TTS are billed separately. Local warnings need no chat AI. Raising the limit does not automatically create useful events.", "Limita consultas de IA por sesión, no todos los costes. Reconocimiento y TTS se facturan aparte. Los avisos locales no necesitan chat IA. Subir el límite no genera automáticamente eventos útiles."]}, "schedule": {"title": "Regelmäßige Funkberichte", "text": ["An/Aus pro Thema; Alle = Grundabstand in Sekunden, −/+ = zufällige Toleranz davor/danach. Beispiel 120 −7/+8: 113–128 s. Planung, keine garantierte Sendezeit: Funkbelegung, Kurvenlast, Flugrunde oder fehlende Werte verschieben Berichte. Ereignisse bleiben unabhängig.", "Toggle each topic. Every = base seconds, −/+ = random earlier/later tolerance. 120 −7/+8 means 113–128 s. This is scheduling, not a guaranteed airtime: traffic on the channel, corner load, push laps or missing values can defer reports. Events stay independent.", "Activa cada tema. Cada = segundos base; −/+ = tolerancia aleatoria antes/después. 120 −7/+8 son 113–128 s. Es planificación, no emisión garantizada: canal ocupado, curvas, vueltas lanzadas o datos ausentes pueden aplazar informes. Los eventos son independientes."]}, "memory": {"title": "Dauerhaftes Fahrergedächtnis", "text": ["Speichert Texte, Wünsche und begrenzte Fakten außerhalb der ZIP. Updates behalten sie bei. Relevante Notizen gehen bei Gesprächen an die KI. Kein Training der Modellgewichte, keine automatische Programmänderung und kein Ersatz für aktuelle Messwerte.", "Stores texts, preferences and bounded facts outside the ZIP, surviving updates. Relevant notes are sent to the AI during conversations. This does not train model weights, change code automatically or replace current measurements.", "Guarda textos, preferencias y hechos limitados fuera del ZIP y los conserva al actualizar. Las notas relevantes se envían a la IA. No entrena pesos del modelo, no cambia código ni sustituye mediciones actuales."]}, "recorder": {"title": "Fahrer, Telemetrie & Diagnose", "text": ["Optionaler lokaler JSONL-Recorder: bis 20 Hz, begrenzt auf 128 MiB je Aufnahme und 512 MiB insgesamt. Erfasst Entscheidungen, Fakten und Software-Zeitstempel, keine vollständigen Mikrofonaufnahmen oder Schlüssel. Logs können Namen und Funktext enthalten; vor Weitergabe prüfen.", "Optional local JSONL recorder: up to 20 Hz, bounded to 128 MiB per capture and 512 MiB total. Records decisions, facts and software timestamps, not full microphone recordings or keys. Logs may contain names and radio text; review before sharing.", "Grabador JSONL local opcional: hasta 20 Hz, limitado a 128 MiB por grabación y 512 MiB en total. Registra decisiones, hechos y tiempos de software, no audio completo ni claves. Puede contener nombres y mensajes; revísalo antes de compartir."]}, "timeout": {"title": "KI-Zeitlimit / Sekunden", "text": ["3–60 Sekunden bis zum Abbruch einer KI-Anfrage. Höher verhindert kurze Timeouts, kann aber veraltete Antworten fördern. Aktualitätsprüfungen bleiben aktiv. Kein Geschwindigkeitsregler für Sara oder die Telemetrie.", "3–60 seconds before an AI request times out. A higher value avoids short timeouts but can allow older replies. Freshness checks remain active. It does not control Sara or telemetry speed.", "3–60 segundos para cancelar una consulta de IA. Un valor alto evita cortes tempranos, pero puede permitir respuestas antiguas. La validación de actualidad sigue activa. No controla la velocidad de Sara ni telemetría."]}, "question": {"title": "Frage an die Crew", "text": ["Textfrage ohne Mikrofon, aber mit denselben Daten-, KI- und Stimmenwegen. Nur bekannte aktuelle Fakten können beantwortet werden. Nicht während der Fahrt tippen; dafür die Funktaste benutzen.", "A typed question uses the same data, AI and voices without the microphone. Only known current facts can be answered. Do not type while driving; use push-to-talk.", "Una pregunta escrita usa los mismos datos, IA y voces, sin micrófono. Solo se pueden responder hechos actuales disponibles. No escribas al conducir; usa el botón de radio."]}, "metrics": {"title": "Abstand", "text": ["Im Rennen sind Klassengegner und physisch nächste Autos unterschiedliche Dinge. Geschätzte Abstände sind mit ≈ markiert. Im Training/Qualifying kann hier eine Bestzeitdifferenz stehen. Keine ungemeldeten Daten erfinden.", "In a race, class rivals and physically nearest cars are different. Estimated gaps carry ≈. Practice/qualifying can show a best-lap difference here. Missing data is not invented.", "En carrera, rivales de clase y coches más cercanos son distintos. Las estimaciones llevan ≈. En entrenamientos/clasificación puede mostrarse diferencia de mejor vuelta. No se inventan datos ausentes."]}};
  help.memberVolume={title:'Funklautstärke',text:['Individueller Pegel zusätzlich zur allgemeinen Funklautstärke. 100 % belässt den bisherigen Pegel; 50 % halbiert die Amplitude. Gilt ab der nächsten Ansage und bei Stimmenproben, ohne neue Clips. 0 % schaltet diese Stimme stumm, auch Saras Warnungen.','Individual level multiplied by the main radio volume. 100% preserves the previous level; 50% halves amplitude. Applies to new calls and voice tests without rebuilding clips. 0% mutes this voice, including Sara’s warnings.','Nivel individual multiplicado por el volumen general. 100 % conserva el nivel; 50 % reduce la amplitud a la mitad. Se aplica a nuevos mensajes y pruebas sin regenerar clips. 0 % silencia la voz, incluidos los avisos de Sara.']};
  help.radioLanguage={title:'Funksprache',text:['Sprache, in der Ben, Mik und Sara sprechen und dich verstehen: Deutsch, Englisch oder Spanisch. Automatisch nimmt die Windows-Sprache (sonst Englisch). Nach einem Wechsel unter Team & Stimmen die Funkclips neu vorbereiten und Sara als Spotter neu erzeugen, dann die App neu starten. Stimmen bei ElevenLabs können mehrere Sprachen sprechen.','Language Ben, Mik and Sara speak and understand: German, English or Spanish. Automatic uses your Windows language (otherwise English). After changing it, prepare the radio clips again and generate Sara’s spotter pack again under Team & voices, then restart the app. ElevenLabs voices can speak several languages.','Idioma en el que Ben, Mik y Sara hablan y te entienden: alemán, inglés o español. Automático usa el idioma de Windows (si no, inglés). Tras cambiarlo, prepara de nuevo los clips de radio y genera otra vez el paquete de Sara en Equipo y voces, y reinicia la aplicación. Las voces de ElevenLabs hablan varios idiomas.']};
  Object.assign(words, {'Lautstärke Ben':['Ben volume','Volumen de Ben'],'Lautstärke Mik':['Mik volume','Volumen de Mik'],'Lautstärke Sara':['Sara volume','Volumen de Sara']});
  // Ohne gespeicherte Wahl: Sprache von Windows übernehmen (DE/EN/ES), sonst Englisch
  let language = 'en';
  try { for (const l of (navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language])) { const c = String(l || '').slice(0, 2).toLowerCase(); if (['de','en','es'].includes(c)) { language = c; break; } } } catch (_) { }
  try { const saved = localStorage.getItem('rrca.uiLanguage'); if (['de','en','es'].includes(saved)) language=saved; } catch (_) { }
  const records=[], attributes=[], seen=new WeakSet();
  const pick = (de,en,es) => language==='en'?en:language==='es'?es:de;
  const patterns = [
    [/^Vorschau(.*)$/, tail=>pick('Vorschau','Preview','Vista previa')+tail],
    [/^(\d+) Themen$/, (n)=>pick(n+' Themen',n+' topics',n+' temas')],
    [/^von (\d+) in deiner Klasse$/, n=>pick('von '+n+' in deiner Klasse','of '+n+' in your class','de '+n+' en tu clase')],
    [/^Runde (\d+)( · Uhr abgelaufen)?$/, (n,end)=>pick('Runde '+n+(end||''),'Lap '+n+(end?' · clock expired':''),'Vuelta '+n+(end?' · tiempo agotado':''))],
    [/^(\d+) Runden verbleibend$/, n=>pick(n+' Runden verbleibend',n+' laps remaining',n+' vueltas restantes')],
    [/^(.*): Datenquelle erreichbar$/, sim=>pick(sim+': Datenquelle erreichbar',sim+': data source reachable',sim+': fuente de datos accesible')],
    [/^Letzte Runde (.*)$/, time=>pick('Letzte Runde '+time,'Last lap '+time,'Última vuelta '+time)],
    [/^hinterlegt (.*)$/, mask=>pick('hinterlegt '+mask,'stored '+mask,'guardada '+mask)],
    [/^(.*) · funkt gerade$/, name=>pick(name+' · funkt gerade',name+' · on the radio',name+' · hablando')],
    [/^(.*) · zuletzt (.*)$/, (name,time)=>pick(name+' · zuletzt '+time,name+' · last '+time,name+' · último '+time)],
    [/^Bestzeitdifferenz zu (.*)$/, name=>pick('Bestzeitdifferenz zu '+name,'Best-lap difference to '+name,'Diferencia de mejor vuelta con '+name)],
    [/^auf (.*) vor dir( · Näherung)?$/, (name,est)=>pick('auf '+name+' vor dir'+(est||''),'to '+name+' ahead'+(est?' · estimate':''),'con '+name+' delante'+(est?' · estimación':''))],
    [/^auf (.*?)( · Näherung)?( · vorne (.*))?$/, (name,est,front,rest)=>pick('auf '+name+(est||'')+(front||''),'to '+name+(est?' · estimate':'')+(front?' · ahead '+rest.replace(' ungefähr ',' approximately '):''),'con '+name+(est?' · estimación':'')+(front?' · delante '+rest.replace(' ungefähr ',' aproximadamente '):''))],
    [/^Diagnose: (.*)$/, value=>pick('Diagnose: ','Diagnostics: ','Diagnóstico: ')+t(value).replace('verworfen=',pick('verworfen=','dropped=','descartados='))],
    [/^Frage an die Crew: (.*)$/, value=>pick('Frage an die Crew: ','Question for the crew: ','Pregunta al equipo: ')+value]
  ];
  function t(text) {
    if (typeof text!=='string') return text;
    const s=text.trim(), row=words[s];
    if (row) return text.replace(s,pick(s,row[0],row[1]));
    for (const [rx,format] of patterns) { const m=s.match(rx); if(m) return text.replace(s,format(...m.slice(1))); }
    return text;
  }
  function scan(root) {
    const walk=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);
    while(walk.nextNode()) {
      const n=walk.currentNode, p=n.parentElement;
      if(seen.has(n)||!p||p.closest('script,style,#rrca-help-dialog,[data-no-i18n]'))continue;
      seen.add(n);
      if(words[n.nodeValue.trim()]) records.push({node:n,de:n.nodeValue,last:n.nodeValue});
    }
    root.querySelectorAll('[title],[placeholder],[aria-label]').forEach(el=>{
      if(el.closest('[data-no-i18n]') && el.tagName!=='SELECT')return;
      for(const key of ['title','placeholder','aria-label']) {
        const value=el.getAttribute(key);
        if(value && words[value.trim()] && !attributes.some(r=>r.el===el&&r.key===key))attributes.push({el,key,de:value});
      }
    });
    refresh();
  }
  function refresh() {
    document.documentElement.lang=language;
    for(const r of records) {
      if(r.node.isConnected && r.node.nodeValue===r.last) { r.node.nodeValue=t(r.de);r.last=r.node.nodeValue; }
    }
    for(const r of attributes) if(r.el.isConnected) r.el.setAttribute(r.key,t(r.de));
    document.querySelectorAll('[data-help]').forEach(b=>{
      const topic=help[b.dataset.help];
      b.setAttribute('aria-label',t('Hilfe')+': '+t(topic.title));
      b.title=t('Hilfe')+': '+t(topic.title);
    });
    const select=document.getElementById('rrca-language'); if(select)select.value=language;
    if(dialog && dialog.open){if(dialog.dataset.document)dialog.querySelector('button').textContent=t('Schließen');else renderHelp(dialog.dataset.topic);}
  }
  let dialog=null,returnFocus=null,fieldNumber=0;
  function renderHelp(key) {
    const h=help[key];dialog.dataset.topic=key;
    dialog.querySelector('h2').textContent=t(h.title);
    dialog.querySelector('p').textContent=h.text[language==='en'?1:language==='es'?2:0];
    dialog.querySelector('button').textContent=t('Schließen');
  }
  function openHelp(key,button) {
    if(!help[key])return;
    delete dialog.dataset.document;dialog.classList.remove('document-dialog');returnFocus=button;renderHelp(key);dialog.showModal();dialog.querySelector('button').focus();
  }
  function openDocument(title,text) {
    if(typeof title!=='string'||typeof text!=='string')return;
    returnFocus=document.activeElement;dialog.dataset.document='true';dialog.classList.add('document-dialog');
    dialog.querySelector('h2').textContent=title;dialog.querySelector('p').textContent=text;dialog.querySelector('button').textContent=t('Schließen');
    if(!dialog.open)dialog.showModal();dialog.querySelector('button').focus();
  }
  function button(key) {
    const b=document.createElement('button');b.type='button';b.className='help-button';b.dataset.help=key;b.textContent='?';
    b.addEventListener('click',e=>{e.preventDefault();e.stopPropagation();openHelp(key,b);});return b;
  }
  function attach(selector,key) {
    document.querySelectorAll(selector).forEach(el=>{
      if(el.dataset.hasHelp)return;el.dataset.hasHelp='true';
      if(el.matches('input,select')) {
        const wrapper=el.closest('label.field,label.voice-choice');
        if(wrapper) {
          // Keep one associated label per field; the help button is a sibling, never nested in a label.
          const div=document.createElement('div');for(const a of wrapper.attributes)div.setAttribute(a.name,a.value);
          const caption=document.createElement('label');el.id=el.id||'rrca-help-field-'+key+'-'+(++fieldNumber);
          caption.htmlFor=el.id;caption.className='field-caption';
          while(wrapper.firstChild && wrapper.firstChild!==el)caption.appendChild(wrapper.firstChild);
          const heading=document.createElement('div');heading.className='field-heading';heading.append(caption,button(key));div.append(heading);
          while(wrapper.firstChild)div.appendChild(wrapper.firstChild);
          wrapper.replaceWith(div);return;
        }
        const label=el.closest('label'); if(label){
          if(label.parentElement.matches('.member-row')){const controls=document.createElement('div');controls.className='role-control';label.replaceWith(controls);controls.append(label,button(key));}
          else label.after(button(key));return;}
      }
      if(el.matches('span,summary')) el.appendChild(button(key)); else el.after(button(key));
    });refresh();
  }
  function setLanguage(value) {
    if(!['de','en','es'].includes(value))return;
    language=value;try{localStorage.setItem('rrca.uiLanguage',value);}catch(_){}
    refresh();document.dispatchEvent(new Event('rrca-language-changed'));
  }
  dialog=document.createElement('dialog');dialog.id='rrca-help-dialog';dialog.className='help-dialog';dialog.setAttribute('aria-labelledby','rrca-help-title');
  dialog.innerHTML='<h2 id="rrca-help-title"></h2><p></p><button type="button" class="button primary"></button>';
  dialog.querySelector('button').addEventListener('click',()=>{dialog.close();if(returnFocus&&returnFocus.isConnected)returnFocus.focus();});
  dialog.addEventListener('close',()=>{if(returnFocus&&returnFocus.isConnected)returnFocus.focus();});
  document.body.appendChild(dialog);
  window.RRCAI18n={t,pick,scan,attach,setLanguage,openDocument,get language(){return language;},helpKeys:Object.keys(help)};
  const top=document.querySelector('.top-right');
  const wrap=document.createElement('label');wrap.className='language-choice';wrap.innerHTML='<span>Oberflächensprache</span><select id="rrca-language" aria-label="Oberflächensprache"><option value="de">Deutsch</option><option value="en">English</option><option value="es">Español</option></select>';
  top.prepend(wrap);wrap.querySelector('select').addEventListener('change',e=>setLanguage(e.target.value));wrap.after(button('language'));
  const note=document.createElement('p');note.className='note language-note';note.textContent='Die Sprachwahl übersetzt die Oberfläche und Hilfen. Die Sprache des Funks stellst du unter KI & Funk ein.';document.querySelector('.top').after(note);
  const fields={
    '#rrca-game':'game','#rrca-auto':'game','#rrca-ben-volume':'memberVolume','#rrca-mik-volume':'memberVolume','#rrca-sara-volume':'memberVolume','#rrca-messages-volume':'volume','#rrca-background-volume':'volume',
    '[data-member]':'roles','[data-voice-select]':'voices','[data-cmd=prepareVoices]':'clips','[data-cmd=saraPack]':'voices',
    '#rrca-phrase-situation':'phrases','#rrca-phrase-variant':'phrases','#rrca-mik-numbers':'numbers',
    '#rrca-mic':'mic','#rrca-ptt':'mic','#rrca-radio-effect':'filter','#rrca-keys summary':'keys',
    '[data-setting=driverName]':'name','[data-setting=driverNickname]':'name','[data-setting=radioMode]':'mode','[data-setting=radioLanguage]':'radioLanguage',
    '[data-setting=fastModel]':'fast','[data-setting=deepModel]':'deep','[data-setting=sttModel]':'stt',
    '[data-setting=ttsModel]':'tts','[data-setting=reasoning]':'reasoning','[data-setting=callLimit]':'limit',
    '#rrca-send-names':'keys','#rrca-radio-preset':'schedule','#rrca-memory':'memory','#rrca-recorder':'recorder','[data-setting=timeout]':'timeout',
    '#rrca-send':'question','#m-gap-sub':'metrics'
  };
  for(const [selector,key] of Object.entries(fields))attach(selector,key);
  scan(document.body);
})();
